export const EMBEDDED_ADMIN_HTML = "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>لوحة التحكم الإدارية المتكاملة | متجر زهرة (Zahra Store)</title>\n  <!-- Google Fonts: Cairo -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@300;400;500;600;700;800;900&display=swap\" rel=\"stylesheet\" />\n  <!-- Tailwind CSS CDN -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Font Awesome Icons -->\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css\" />\n  <!-- Chart.js CDN -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: '#fdf2f8',\n              100: '#fce7f3',\n              200: '#fbcfe8',\n              300: '#f9a8d4',\n              400: '#f472b6',\n              500: '#ec4899',\n              600: '#db2777',\n              700: '#be185d',\n              800: '#9d174d',\n              900: '#831843',\n            },\n          },\n          fontFamily: {\n            cairo: ['Cairo', 'sans-serif'],\n          }\n        }\n      }\n    }\n  </script>\n  <style>\n    body { font-family: 'Cairo', sans-serif; }\n    .custom-scrollbar::-webkit-scrollbar { width: 6px; height: 6px; }\n    .custom-scrollbar::-webkit-scrollbar-track { background: #f8fafc; }\n    .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }\n    .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }\n  </style>\n</head>\n<body class=\"bg-slate-50 text-slate-800 antialiased min-h-screen flex flex-col\">\n\n  <!-- ════════════ LOGIN OVERLAY (when unauthenticated) ════════════ -->\n  <div id=\"loginScreen\" class=\"fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-3xl max-w-md w-full p-8 shadow-2xl border border-slate-100 text-right space-y-6\">\n      <div class=\"text-center space-y-2\">\n        <div class=\"w-16 h-16 rounded-2xl bg-gradient-to-tr from-brand-700 to-brand-500 mx-auto flex items-center justify-center text-white text-3xl shadow-lg shadow-brand-500/30\">\n          <i class=\"fa-solid fa-spa\"></i>\n        </div>\n        <h2 class=\"text-xl font-black text-slate-900\">تسجيل الدخول إلى لوحة التحكم</h2>\n        <p class=\"text-xs text-slate-500\">متجر زهرة للمفروشات وتلبيسات الكراسي (Supabase & NestJS)</p>\n      </div>\n\n      <form onsubmit=\"handleLoginSubmit(event)\" class=\"space-y-4 text-xs\">\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">البريد الإلكتروني</label>\n          <div class=\"relative\">\n            <input type=\"email\" id=\"loginEmail\" required value=\"admin@zahra-store.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-3 pl-10 focus:border-brand-500 focus:outline-none font-medium\" />\n            <i class=\"fa-solid fa-envelope absolute left-3 top-3.5 text-slate-400\"></i>\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">كلمة المرور</label>\n          <div class=\"relative\">\n            <input type=\"password\" id=\"loginPassword\" required value=\"admin123456\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl py-3 px-3 pl-10 focus:border-brand-500 focus:outline-none font-medium\" />\n            <i class=\"fa-solid fa-lock absolute left-3 top-3.5 text-slate-400\"></i>\n          </div>\n        </div>\n\n        <button type=\"submit\" id=\"loginSubmitBtn\" class=\"w-full py-3 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold text-sm shadow-md shadow-brand-600/20 transition-all flex items-center justify-center gap-2\">\n          <span>دخول لوحة التحكم</span>\n          <i class=\"fa-solid fa-arrow-left\"></i>\n        </button>\n\n        <div class=\"bg-brand-50 p-3 rounded-xl border border-brand-100 text-[11px] text-brand-800 space-y-1\">\n          <div class=\"font-bold\">🔑 بيانات الدخول الافتراضية للمدير:</div>\n          <div>البريد: <span class=\"font-mono font-semibold\">admin@zahra-store.com</span></div>\n          <div>كلمة المرور: <span class=\"font-mono font-semibold\">admin123456</span></div>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- ════════════ TOP NAVIGATION BAR ════════════ -->\n  <header class=\"bg-white border-b border-slate-200 sticky top-0 z-30 shadow-sm\">\n    <div class=\"max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between\">\n      <div class=\"flex items-center gap-3\">\n        <div class=\"w-10 h-10 rounded-xl bg-gradient-to-tr from-brand-700 to-brand-500 flex items-center justify-center text-white shadow-md shadow-brand-500/20\">\n          <i class=\"fa-solid fa-spa text-xl\"></i>\n        </div>\n        <div>\n          <h1 class=\"text-lg font-bold text-slate-900 leading-none\">متجر زهرة</h1>\n          <span class=\"text-xs text-brand-600 font-medium\">لوحة التحكم والإدارة المالية والسحابية (Supabase)</span>\n        </div>\n      </div>\n\n      <div class=\"flex items-center gap-3\">\n        <button onclick=\"refreshCurrentTab()\" class=\"p-2 text-slate-500 hover:text-brand-600 hover:bg-slate-100 rounded-lg transition-colors\" title=\"تحديث البيانات\">\n          <i class=\"fa-solid fa-arrows-rotate\"></i>\n        </button>\n        <a href=\"/api/docs\" target=\"_blank\" class=\"hidden sm:inline-flex items-center gap-2 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-brand-600 bg-slate-100 hover:bg-brand-50 border border-slate-200 rounded-lg transition-colors\">\n          <i class=\"fa-solid fa-book text-brand-500\"></i>\n          <span>توثيق Swagger</span>\n        </a>\n        <a href=\"http://localhost:3000\" target=\"_blank\" class=\"hidden sm:inline-flex items-center gap-2 px-3 py-1.5 text-xs font-semibold text-slate-600 hover:text-brand-600 bg-slate-100 hover:bg-brand-50 border border-slate-200 rounded-lg transition-colors\">\n          <i class=\"fa-solid fa-store text-emerald-500\"></i>\n          <span>المتجر</span>\n        </a>\n        \n        <div class=\"h-6 w-px bg-slate-200 hidden sm:block\"></div>\n\n        <div class=\"flex items-center gap-3\">\n          <div class=\"w-9 h-9 rounded-full bg-brand-100 text-brand-700 font-bold flex items-center justify-center text-sm border border-brand-200\" id=\"userAvatar\">\n            م\n          </div>\n          <div class=\"hidden md:block text-right\">\n            <div class=\"text-xs font-bold text-slate-800\" id=\"userNameDisplay\">مدير متجر زهرة</div>\n            <div class=\"text-[10px] text-emerald-600 font-medium flex items-center gap-1\" id=\"userRoleBadge\">\n              <span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>\n              مدير عام (ADMIN)\n            </div>\n          </div>\n          <button onclick=\"handleLogout()\" title=\"تسجيل الخروج الفعلي\" class=\"text-slate-400 hover:text-rose-600 p-2 rounded-lg hover:bg-rose-50 transition-colors flex items-center gap-1 text-xs font-bold\">\n            <i class=\"fa-solid fa-arrow-right-from-bracket text-sm\"></i>\n            <span class=\"hidden sm:inline\">خروج</span>\n          </button>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <!-- ════════════ MAIN LAYOUT ════════════ -->\n  <div class=\"flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 flex flex-col md:flex-row gap-6\">\n\n    <!-- Sidebar Navigation -->\n    <aside class=\"w-full md:w-64 shrink-0\">\n      <nav class=\"bg-white rounded-2xl border border-slate-200 p-2 shadow-sm space-y-1 sticky top-22\">\n        <button onclick=\"switchTab('overview')\" id=\"tab-btn-overview\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-brand-700 bg-brand-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-chart-pie w-5 text-center text-brand-600\"></i>\n            <span>نظرة عامة وأرباح</span>\n          </div>\n        </button>\n\n        <button onclick=\"switchTab('products')\" id=\"tab-btn-products\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-tags w-5 text-center text-slate-400\"></i>\n            <span>إدارة المنتجات</span>\n          </div>\n          <span id=\"badge-products-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('categories')\" id=\"tab-btn-categories\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-folder-tree w-5 text-center text-slate-400\"></i>\n            <span>الأقسام والتصنيفات</span>\n          </div>\n          <span id=\"badge-categories-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('orders')\" id=\"tab-btn-orders\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-box-archive w-5 text-center text-slate-400\"></i>\n            <span>إدارة الطلبات</span>\n          </div>\n          <span id=\"badge-pending-orders\" class=\"bg-amber-100 text-amber-800 text-[11px] font-bold px-2 py-0.5 rounded-full hidden\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('custom-chairs')\" id=\"tab-btn-custom-chairs\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-chair w-5 text-center text-slate-400\"></i>\n            <span>طلبات تفصيل الكراسي</span>\n          </div>\n          <span id=\"badge-new-chairs\" class=\"bg-rose-100 text-rose-700 text-[11px] font-bold px-2 py-0.5 rounded-full hidden\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('customers')\" id=\"tab-btn-customers\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-users w-5 text-center text-slate-400\"></i>\n            <span>العملاء (Clients CRM)</span>\n          </div>\n          <span id=\"badge-clients-count\" class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">0</span>\n        </button>\n\n        <button onclick=\"switchTab('expenses')\" id=\"tab-btn-expenses\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-receipt w-5 text-center text-slate-400\"></i>\n            <span>المصروفات والتكاليف</span>\n          </div>\n        </button>\n\n        <button onclick=\"switchTab('shipping')\" id=\"tab-btn-shipping\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-truck-fast w-5 text-center text-slate-400\"></i>\n            <span>الشحن والمحافظات</span>\n          </div>\n          <span class=\"bg-slate-100 text-slate-600 text-[11px] font-bold px-2 py-0.5 rounded-full\">27</span>\n        </button>\n\n        <button onclick=\"switchTab('staff')\" id=\"tab-btn-staff\" class=\"w-full flex items-center justify-between px-3 py-2.5 rounded-xl font-medium text-sm transition-all text-slate-600 hover:bg-slate-50\">\n          <div class=\"flex items-center gap-3\">\n            <i class=\"fa-solid fa-user-shield w-5 text-center text-slate-400\"></i>\n            <span>المشرفين والصلاحيات</span>\n          </div>\n        </button>\n      </nav>\n\n      <!-- Cloud Status Box -->\n      <div class=\"bg-white rounded-2xl border border-slate-200 p-4 mt-4 shadow-sm text-xs text-slate-600 space-y-2\">\n        <div class=\"font-bold text-slate-800 flex items-center gap-2\">\n          <i class=\"fa-solid fa-cloud text-emerald-500\"></i>\n          قاعدة بيانات Supabase الحية\n        </div>\n        <div class=\"flex items-center justify-between text-[11px] pt-1 border-t border-slate-100\">\n          <span>المشروع:</span>\n          <span class=\"text-emerald-700 font-mono font-bold\">oyiqebjljvmjuxhsivqq</span>\n        </div>\n        <div class=\"flex items-center justify-between text-[11px]\">\n          <span>قاعدة البيانات:</span>\n          <span class=\"text-emerald-600 font-semibold flex items-center gap-1\">\n            <span class=\"w-2 h-2 rounded-full bg-emerald-500 inline-block animate-ping\"></span> متصلة وحية\n          </span>\n        </div>\n      </div>\n    </aside>\n\n    <!-- Main Content Dynamic Panels -->\n    <main class=\"flex-1 min-w-0\">\n\n      <!-- ════ 1. OVERVIEW & FINANCIALS PANEL ════ -->\n      <section id=\"panel-overview\" class=\"space-y-6\">\n        <!-- 6 KPI CARDS (Financials & Metrics) -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n          <!-- Total Revenue -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">إجمالي الإيرادات (Revenue)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-revenue\">0 ج.م</div>\n              <div class=\"text-[11px] text-emerald-600 mt-1 flex items-center gap-1 font-semibold\">\n                <i class=\"fa-solid fa-arrow-trend-up\"></i>\n                مجموع الطلبات المسجلة\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-coins\"></i>\n            </div>\n          </div>\n\n          <!-- Total Expenses -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">إجمالي المصروفات (Expenses)</div>\n              <div class=\"text-2xl font-black text-rose-600 mt-1\" id=\"kpi-expenses\">0 ج.م</div>\n              <div class=\"text-[11px] text-rose-600 mt-1 flex items-center gap-1 font-semibold\">\n                <i class=\"fa-solid fa-arrow-trend-down\"></i>\n                تكاليف وخامات وشحن وتسويق\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-receipt\"></i>\n            </div>\n          </div>\n\n          <!-- Net Profit -->\n          <div class=\"bg-gradient-to-tr from-emerald-600 to-teal-500 p-5 rounded-2xl text-white shadow-md flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-emerald-100\">صافي الأرباح (Net Profit)</div>\n              <div class=\"text-3xl font-black mt-1\" id=\"kpi-net-profit\">0 ج.م</div>\n              <div class=\"text-[11px] text-emerald-100 mt-1 font-semibold\">\n                الإيرادات - المصروفات\n              </div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-white/20 text-white flex items-center justify-center text-xl backdrop-blur-sm\">\n              <i class=\"fa-solid fa-chart-line\"></i>\n            </div>\n          </div>\n\n          <!-- Total Orders -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">عدد الطلبات (Orders)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-orders\">0</div>\n              <div class=\"text-[11px] text-amber-600 mt-1 font-semibold\" id=\"kpi-pending-label\">0 طلب معلق</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-amber-50 text-amber-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-box-archive\"></i>\n            </div>\n          </div>\n\n          <!-- Total Products -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">عدد المنتجات (Products)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-products\">0</div>\n              <div class=\"text-[11px] text-slate-400 mt-1\">المنتجات النشطة بالمتجر</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-purple-50 text-purple-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-tags\"></i>\n            </div>\n          </div>\n\n          <!-- Total Clients -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex items-center justify-between\">\n            <div>\n              <div class=\"text-xs font-bold text-slate-500\">عدد العملاء (Clients)</div>\n              <div class=\"text-2xl font-black text-slate-900 mt-1\" id=\"kpi-clients\">0</div>\n              <div class=\"text-[11px] text-slate-400 mt-1\">المسجلين في النظام</div>\n            </div>\n            <div class=\"w-12 h-12 rounded-xl bg-teal-50 text-teal-600 flex items-center justify-center text-xl\">\n              <i class=\"fa-solid fa-users\"></i>\n            </div>\n          </div>\n        </div>\n\n        <!-- Sales Chart & Low Stock Warning -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-3 gap-6\">\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm lg:col-span-2 space-y-4\">\n            <div class=\"flex items-center justify-between\">\n              <h2 class=\"font-bold text-slate-900 text-sm flex items-center gap-2\">\n                <i class=\"fa-solid fa-chart-line text-brand-600\"></i>\n                مخطط المبيعات اليومية\n              </h2>\n              <span class=\"text-xs text-slate-400 font-mono\">بيانات حية من Supabase</span>\n            </div>\n            <div class=\"h-64 relative\">\n              <canvas id=\"salesChartCanvas\"></canvas>\n            </div>\n          </div>\n\n          <!-- Low Stock Alert -->\n          <div class=\"bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4\">\n            <h2 class=\"font-bold text-slate-900 text-sm flex items-center gap-2 text-rose-600\">\n              <i class=\"fa-solid fa-triangle-exclamation\"></i>\n              تنبيهات انخفاض المخزون\n            </h2>\n            <div id=\"low-stock-list\" class=\"space-y-3\">\n              <!-- populated by JS -->\n            </div>\n          </div>\n        </div>\n\n        <!-- Recent Orders Table -->\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"p-5 border-b border-slate-100 flex items-center justify-between\">\n            <h2 class=\"font-bold text-slate-900 text-sm\">أحدث طلبات الشراء المسجلة</h2>\n            <button onclick=\"switchTab('orders')\" class=\"text-xs text-brand-600 hover:text-brand-700 font-semibold\">\n              عرض كل الطلبات &larr;\n            </button>\n          </div>\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">رقم الطلب</th>\n                  <th class=\"p-3\">العميل</th>\n                  <th class=\"p-3\">المحافظة</th>\n                  <th class=\"p-3\">الإجمالي</th>\n                  <th class=\"p-3\">الحالة</th>\n                  <th class=\"p-3\">التاريخ</th>\n                </tr>\n              </thead>\n              <tbody id=\"overview-orders-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 2. PRODUCTS PANEL (Full CRUD) ════ -->\n      <section id=\"panel-products\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">كتالوج المنتجات السحابي</h2>\n            <p class=\"text-xs text-slate-500\">إضافة وتعديل وحذف المنتجات، التحكم بالمخزون ورفع الصور إلى Supabase Storage</p>\n          </div>\n          <button onclick=\"openProductModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            إضافة منتج جديد\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">المنتج</th>\n                  <th class=\"p-3\">القسم</th>\n                  <th class=\"p-3\">السعر الحالي</th>\n                  <th class=\"p-3\">السعر الأصلي</th>\n                  <th class=\"p-3\">الخصم</th>\n                  <th class=\"p-3\">المخزون</th>\n                  <th class=\"p-3\">حالة التوفر</th>\n                  <th class=\"p-3 text-center\">إجراءات</th>\n                </tr>\n              </thead>\n              <tbody id=\"products-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 3. CATEGORIES PANEL (Full CRUD) ════ -->\n      <section id=\"panel-categories\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">الأقسام والتصنيفات</h2>\n            <p class=\"text-xs text-slate-500\">التحكم في أقسام المتجر، الترتيب، الصور والظهور في الموقع</p>\n          </div>\n          <button onclick=\"openCategoryModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            إضافة قسم جديد\n          </button>\n        </div>\n\n        <div id=\"categories-grid\" class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4\">\n          <!-- populated by JS -->\n        </div>\n      </section>\n\n      <!-- ════ 4. ORDERS PANEL (Full CRUD) ════ -->\n      <section id=\"panel-orders\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-4\">\n          <div class=\"flex items-center gap-2 overflow-x-auto w-full md:w-auto pb-1 md:pb-0\">\n            <button onclick=\"filterOrders('all')\" id=\"btn-order-filter-all\" class=\"px-3 py-1.5 rounded-lg text-xs font-bold bg-brand-600 text-white\">الكل</button>\n            <button onclick=\"filterOrders('pending')\" id=\"btn-order-filter-pending\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">معلق</button>\n            <button onclick=\"filterOrders('confirmed')\" id=\"btn-order-filter-confirmed\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">مؤكد</button>\n            <button onclick=\"filterOrders('processing')\" id=\"btn-order-filter-processing\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">قيد التجهيز</button>\n            <button onclick=\"filterOrders('shipped')\" id=\"btn-order-filter-shipped\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">تم الشحن</button>\n            <button onclick=\"filterOrders('delivered')\" id=\"btn-order-filter-delivered\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">تم التسليم</button>\n            <button onclick=\"filterOrders('cancelled')\" id=\"btn-order-filter-cancelled\" class=\"px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700\">ملغي</button>\n          </div>\n\n          <div class=\"relative w-full md:w-72\">\n            <input type=\"text\" id=\"orderSearchInput\" oninput=\"handleOrderSearch(this.value)\" placeholder=\"بحث برقم الطلب، الاسم، أو الهاتف...\" class=\"w-full text-xs bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 pr-9 focus:outline-none focus:border-brand-500 font-medium\" />\n            <i class=\"fa-solid fa-search absolute right-3 top-3 text-slate-400 text-xs\"></i>\n          </div>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">رقم الطلب</th>\n                  <th class=\"p-3\">العميل والهاتف</th>\n                  <th class=\"p-3\">العنوان والمحافظة</th>\n                  <th class=\"p-3\">المنتجات</th>\n                  <th class=\"p-3\">الإجمالي</th>\n                  <th class=\"p-3\">طريقة الدفع</th>\n                  <th class=\"p-3\">الحالة</th>\n                  <th class=\"p-3 text-center\">إجراءات</th>\n                </tr>\n              </thead>\n              <tbody id=\"orders-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 5. CUSTOM CHAIRS PANEL ════ -->\n      <section id=\"panel-custom-chairs\" class=\"space-y-4 hidden\">\n        <div class=\"bg-gradient-to-r from-brand-800 to-brand-600 rounded-2xl p-6 text-white shadow-md flex flex-col md:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"text-lg font-black flex items-center gap-2\">\n              <i class=\"fa-solid fa-chair text-amber-300\"></i>\n              شاشة طلبات تفصيل وتلبيسات الكراسي (العمولة)\n            </h2>\n            <p class=\"text-xs text-brand-100 mt-1 max-w-2xl leading-relaxed\">\n              الكراسي المرفوعة من العملاء مع صور كراسيهم الخاصة لتفصيل تلبيسة بالمللي (+200 جنيه). تواصل مع العميل بنقرة واحدة عبر الواتساب لتأكيد المقاسات.\n            </p>\n          </div>\n          <button onclick=\"loadChairRequests()\" class=\"px-4 py-2 bg-white/10 hover:bg-white/20 backdrop-blur rounded-xl text-xs font-bold transition-colors\">\n            <i class=\"fa-solid fa-rotate-right ml-1\"></i>\n            تحديث الطلبات\n          </button>\n        </div>\n\n        <!-- Custom Chair Cards Grid -->\n        <div id=\"chair-requests-grid\" class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- populated by JS -->\n        </div>\n      </section>\n\n      <!-- ════ 6. CLIENTS / CUSTOMERS CRM PANEL (Full CRUD) ════ -->\n      <section id=\"panel-customers\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">سجل العملاء وإدارة العلاقات (Clients CRM)</h2>\n            <p class=\"text-xs text-slate-500\">إضافة عملاء يدويين، استعراض سجل طلباتهم، وتواصل واتساب مباشر</p>\n          </div>\n          <button onclick=\"openCustomerModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-user-plus\"></i>\n            إضافة عميل جديد\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">العميل</th>\n                  <th class=\"p-3\">رقم الهاتف</th>\n                  <th class=\"p-3\">المحافظة / المدينة</th>\n                  <th class=\"p-3\">عدد الطلبات</th>\n                  <th class=\"p-3\">إجمالي الإنفاق</th>\n                  <th class=\"p-3 text-center\">إجراءات</th>\n                </tr>\n              </thead>\n              <tbody id=\"customers-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 7. EXPENSES PANEL (Accounting & Financials) ════ -->\n      <section id=\"panel-expenses\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">إدارة المصروفات والتكاليف (Expenses)</h2>\n            <p class=\"text-xs text-slate-500\">تسجيل الخامات، تكاليف الشحن، الحملات الإعلانية، والإيجارات لحساب صافي الربح بدقة</p>\n          </div>\n          <button onclick=\"openExpenseModal()\" class=\"px-4 py-2.5 bg-rose-600 hover:bg-rose-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-plus\"></i>\n            إضافة بند مصروف جديد\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">بند المصروف</th>\n                  <th class=\"p-3\">التصنيف</th>\n                  <th class=\"p-3\">المبلغ (ج.م)</th>\n                  <th class=\"p-3\">التاريخ</th>\n                  <th class=\"p-3\">ملاحظات</th>\n                  <th class=\"p-3 text-center\">إجراء</th>\n                </tr>\n              </thead>\n              <tbody id=\"expenses-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 8. SHIPPING PANEL (Translated with explicit Arabic Badges) ════ -->\n      <section id=\"panel-shipping\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">مناطق الشحن ومحافظات مصر (27 محافظة)</h2>\n            <p class=\"text-xs text-slate-500\">تعديل تكاليف الشحن والمدة التقديرية وتفعيل/تعطيل التوصيل لأي محافظة</p>\n          </div>\n          <div class=\"text-xs text-emerald-600 font-semibold flex items-center gap-1.5 bg-emerald-50 px-3 py-1.5 rounded-xl border border-emerald-100\">\n            <i class=\"fa-solid fa-check-circle\"></i>\n            متصلة سحابياً مع Supabase\n          </div>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">المحافظة</th>\n                  <th class=\"p-3\">تكلفة الشحن (ج.م)</th>\n                  <th class=\"p-3\">مدة التوصيل التقديرية</th>\n                  <th class=\"p-3\">حالة التوصيل للشحن</th>\n                  <th class=\"p-3 text-center\">حفظ التعديل</th>\n                </tr>\n              </thead>\n              <tbody id=\"shipping-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- ════ 9. STAFF & ROLES PANEL (RBAC & Permissions) ════ -->\n      <section id=\"panel-staff\" class=\"space-y-4 hidden\">\n        <div class=\"bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col sm:flex-row items-center justify-between gap-4\">\n          <div>\n            <h2 class=\"font-bold text-slate-900 text-base\">إدارة المشرفين والأدوار (Roles & Permissions)</h2>\n            <p class=\"text-xs text-slate-500\">التحكم في صلاحيات الوصول (مدير عام ADMIN، مشرف عمليات MANAGER، خدمة عملاء SUPPORT)</p>\n          </div>\n          <button onclick=\"openStaffModal()\" class=\"px-4 py-2.5 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-sm transition-colors flex items-center gap-2\">\n            <i class=\"fa-solid fa-user-shield\"></i>\n            إضافة مشرف جديد\n          </button>\n        </div>\n\n        <div class=\"bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-right text-xs\">\n              <thead class=\"bg-slate-50 text-slate-500 font-bold border-b border-slate-100\">\n                <tr>\n                  <th class=\"p-3\">المشرف</th>\n                  <th class=\"p-3\">البريد الإلكتروني</th>\n                  <th class=\"p-3\">الرتبة والصلاحية</th>\n                  <th class=\"p-3\">الحالة</th>\n                  <th class=\"p-3\">تاريخ الإنشاء</th>\n                  <th class=\"p-3 text-center\">إجراء</th>\n                </tr>\n              </thead>\n              <tbody id=\"staff-table-tbody\" class=\"divide-y divide-slate-100 text-slate-700\">\n                <!-- populated by JS -->\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- ════════════ MODALS (All in-place without native alerts) ════════════ -->\n\n  <!-- 1. DELETE CONFIRMATION DIALOG MODAL -->\n  <div id=\"deleteConfirmModal\" class=\"fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[90] flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-sm w-full p-6 shadow-2xl text-center space-y-4\">\n      <div class=\"w-14 h-14 rounded-2xl bg-rose-100 text-rose-600 flex items-center justify-center text-2xl mx-auto\">\n        <i class=\"fa-solid fa-triangle-exclamation\"></i>\n      </div>\n      <div>\n        <h3 class=\"font-black text-base text-slate-900\" id=\"delModalTitle\">تأكيد عملية الحذف</h3>\n        <p class=\"text-xs text-slate-500 mt-1\" id=\"delModalDesc\">هل أنت متأكد من رغبتك في حذف هذا العنصر نهائياً من قاعدة بيانات Supabase؟ لا يمكن التراجع عن هذا الإجراء.</p>\n      </div>\n      <div class=\"flex items-center justify-center gap-3 pt-2\">\n        <button onclick=\"closeDeleteModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold text-xs\">إلغاء</button>\n        <button id=\"delModalConfirmBtn\" class=\"px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold text-xs shadow-md shadow-rose-600/20\">تأكيد الحذف</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. PRODUCT (Add / Edit) MODAL -->\n  <div id=\"productModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-2xl w-full p-6 max-h-[90vh] overflow-y-auto custom-scrollbar shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"productModalTitle\">إضافة منتج جديد</h3>\n        <button onclick=\"closeProductModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"productForm\" onsubmit=\"handleProductSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"prodEditId\" value=\"\" />\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">اسم المنتج بالعربية *</label>\n            <input type=\"text\" id=\"prodName\" required placeholder=\"مثال: طقم تلبيسات كراسي سفرة 6 قطع\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">المعرف الفريد (Slug) *</label>\n            <input type=\"text\" id=\"prodSlug\" required placeholder=\"chair-cover-elastic\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">القسم *</label>\n            <select id=\"prodCategory\" required class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\"></select>\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">السعر الحالي (ج.م) *</label>\n            <input type=\"number\" id=\"prodPrice\" required min=\"1\" step=\"0.5\" placeholder=\"150\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">السعر الأصلي (قبل الخصم)</label>\n            <input type=\"number\" id=\"prodOriginalPrice\" min=\"1\" step=\"0.5\" placeholder=\"220\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">نسبة الخصم %</label>\n            <input type=\"number\" id=\"prodDiscount\" min=\"0\" max=\"100\" placeholder=\"32\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">الكمية بالمخزون</label>\n            <input type=\"number\" id=\"prodStock\" min=\"0\" value=\"20\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">الخامة</label>\n            <input type=\"text\" id=\"prodMaterial\" placeholder=\"ليكرا جاكار مطاطية\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">وصف المنتج</label>\n          <textarea id=\"prodDescription\" rows=\"3\" placeholder=\"اكتب مواصفات المنتج...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\"></textarea>\n        </div>\n\n        <!-- Supabase Storage Image Upload -->\n        <div class=\"bg-slate-50 p-4 rounded-xl border border-slate-200 space-y-2\">\n          <label class=\"block font-bold text-slate-700\">صورة المنتج (رفع مباشر إلى Supabase Storage)</label>\n          <div class=\"flex items-center gap-3\">\n            <input type=\"file\" id=\"prodImageFile\" accept=\"image/*\" class=\"text-xs file:ml-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-bold file:bg-brand-50 file:text-brand-700 hover:file:bg-brand-100 cursor-pointer\" />\n            <button type=\"button\" onclick=\"uploadProductImage()\" class=\"px-3 py-1.5 bg-brand-700 text-white rounded-lg font-bold text-xs hover:bg-brand-800 transition-colors\">\n              <i class=\"fa-solid fa-cloud-arrow-up ml-1\"></i> رفع الصورة\n            </button>\n          </div>\n          <input type=\"text\" id=\"prodImageUrl\" placeholder=\"أو أدخل رابط الصورة...\" class=\"w-full bg-white border border-slate-200 rounded-lg p-2 focus:border-brand-500 focus:outline-none text-[11px]\" />\n          <div id=\"prodImagePreviewContainer\" class=\"hidden mt-2\">\n            <img id=\"prodImagePreview\" src=\"\" class=\"w-20 h-20 rounded-xl object-cover border border-slate-200\" />\n          </div>\n        </div>\n\n        <div class=\"flex flex-wrap gap-4 pt-1\">\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodInStock\" checked class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">متوفر في المخزون</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsFeatured\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">منتج مميز (Featured)</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsOnSale\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">عرض وخصم (Sale)</span>\n          </label>\n          <label class=\"flex items-center gap-2 cursor-pointer\">\n            <input type=\"checkbox\" id=\"prodIsChairCover\" class=\"rounded text-brand-600 w-4 h-4\" />\n            <span class=\"font-bold text-slate-700\">تلبيسة كراسي (تفعيل خيار العمولة)</span>\n          </label>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeProductModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">إلغاء</button>\n          <button type=\"submit\" id=\"prodSubmitBtn\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">حفظ المنتج</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 3. CATEGORY (Add / Edit) MODAL -->\n  <div id=\"categoryModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-lg w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"categoryModalTitle\">إضافة قسم جديد</h3>\n        <button onclick=\"closeCategoryModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"categoryForm\" onsubmit=\"handleCategorySubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"catEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">اسم القسم بالعربية *</label>\n          <input type=\"text\" id=\"catName\" required placeholder=\"مفروشات غرف المعيشة\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">المعرف الفريد (Slug) *</label>\n          <input type=\"text\" id=\"catSlug\" required placeholder=\"living-room\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">الوصف</label>\n          <input type=\"text\" id=\"catDescription\" placeholder=\"وصف موجز للقسم...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">رابط صورة القسم</label>\n          <input type=\"text\" id=\"catImageUrl\" placeholder=\"https://...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none text-[11px]\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">ترتيب الظهور</label>\n            <input type=\"number\" id=\"catSortOrder\" value=\"1\" min=\"1\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div class=\"flex items-center gap-2 pt-6\">\n            <input type=\"checkbox\" id=\"catIsFeatured\" checked class=\"rounded text-brand-600 w-4 h-4\" />\n            <label for=\"catIsFeatured\" class=\"font-bold text-slate-700 cursor-pointer\">قسم مميز</label>\n          </div>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeCategoryModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">إلغاء</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">حفظ القسم</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 4. CUSTOMER / CLIENT (Add / Edit) MODAL -->\n  <div id=\"customerModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-lg w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\" id=\"customerModalTitle\">إضافة عميل جديد</h3>\n        <button onclick=\"closeCustomerModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"customerForm\" onsubmit=\"handleCustomerSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <input type=\"hidden\" id=\"custEditId\" value=\"\" />\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">الاسم الكامل *</label>\n          <input type=\"text\" id=\"custName\" required placeholder=\"سارة أحمد محمود\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">رقم الهاتف (محمول) *</label>\n            <input type=\"text\" id=\"custPhone\" required placeholder=\"01012345678\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-mono\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">البريد الإلكتروني</label>\n            <input type=\"email\" id=\"custEmail\" placeholder=\"client@example.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">المحافظة</label>\n            <input type=\"text\" id=\"custGovernorate\" placeholder=\"القاهرة\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">المدينة / الحي</label>\n            <input type=\"text\" id=\"custCity\" placeholder=\"مدينة نصر\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n          </div>\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">العنوان التفصيلي</label>\n          <input type=\"text\" id=\"custAddress\" placeholder=\"الشارع، رقم العمارة، الشقة...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">ملاحظات العميل</label>\n          <input type=\"text\" id=\"custNotes\" placeholder=\"ملاحظات تفضيلات التسليم...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeCustomerModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">إلغاء</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">حفظ العميل على Supabase</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 5. EXPENSE (Add) MODAL -->\n  <div id=\"expenseModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-md w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\">إضافة بند مصروف جديد</h3>\n        <button onclick=\"closeExpenseModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"expenseForm\" onsubmit=\"handleExpenseSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">بيان / بند المصروف *</label>\n          <input type=\"text\" id=\"expTitle\" required placeholder=\"مثال: شراء أقمشة ليكرا جاكار تركي\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div class=\"grid grid-cols-2 gap-4\">\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">المبلغ (ج.م) *</label>\n            <input type=\"number\" id=\"expAmount\" required min=\"1\" step=\"0.5\" placeholder=\"1500\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-bold\" />\n          </div>\n          <div>\n            <label class=\"block font-bold text-slate-700 mb-1\">التصنيف *</label>\n            <select id=\"expCategory\" required class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\">\n              <option value=\"خامات_وتفصيل\">خامات وتفصيل أقمشة</option>\n              <option value=\"بضاعة\">شراء بضاعة</option>\n              <option value=\"شحن\">تكاليف شحن ونقل</option>\n              <option value=\"تسويق\">تسويق وإعلانات</option>\n              <option value=\"إيجار_ومصاريف\">إيجار ومصاريف تشغيل</option>\n              <option value=\"أخرى\">أخرى</option>\n            </select>\n          </div>\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">ملاحظات إضافية</label>\n          <input type=\"text\" id=\"expNotes\" placeholder=\"ملاحظات توثيق الفاتورة...\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeExpenseModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">إلغاء</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-rose-600 hover:bg-rose-700 text-white rounded-xl font-bold shadow-sm\">تسجيل المصروف</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 6. STAFF / ROLES (Add) MODAL -->\n  <div id=\"staffModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-md w-full p-6 shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <h3 class=\"font-bold text-base text-slate-900\">إضافة مشرف وتحديد الصلاحيات</h3>\n        <button onclick=\"closeStaffModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <form id=\"staffForm\" onsubmit=\"handleStaffSubmit(event)\" class=\"mt-4 space-y-4 text-xs\">\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">الاسم الكامل للمشرف *</label>\n          <input type=\"text\" id=\"staffName\" required placeholder=\"أحمد سعيد\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">البريد الإلكتروني *</label>\n          <input type=\"email\" id=\"staffEmail\" required placeholder=\"staff@zahra-store.com\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">كلمة المرور *</label>\n          <input type=\"password\" id=\"staffPassword\" required minlength=\"6\" placeholder=\"******\" class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none\" />\n        </div>\n        <div>\n          <label class=\"block font-bold text-slate-700 mb-1\">الدور والصلاحيات (Role) *</label>\n          <select id=\"staffRole\" required class=\"w-full bg-slate-50 border border-slate-200 rounded-xl p-2.5 focus:border-brand-500 focus:outline-none font-semibold\">\n            <option value=\"ADMIN\">مدير عام (ADMIN) - كامل الصلاحيات والمالية</option>\n            <option value=\"MANAGER\">مشرف عمليات (MANAGER) - إدارة المنتجات والطلبات والعملاء</option>\n            <option value=\"SUPPORT\">خدمة عملاء (SUPPORT) - متابعة الطلبات والرد على الكراسي</option>\n          </select>\n        </div>\n\n        <div class=\"mt-6 flex items-center justify-end gap-3 pt-4 border-t border-slate-100\">\n          <button type=\"button\" onclick=\"closeStaffModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold\">إلغاء</button>\n          <button type=\"submit\" class=\"px-5 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold shadow-sm\">إضافة المشرف</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- 7. ORDER DETAILS / INVOICE MODAL -->\n  <div id=\"orderModal\" class=\"fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"bg-white rounded-2xl max-w-2xl w-full p-6 max-h-[90vh] overflow-y-auto custom-scrollbar shadow-xl text-right\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <div>\n          <h3 class=\"font-bold text-base text-slate-900\" id=\"modalOrderNumber\">تفاصيل الطلب</h3>\n          <span class=\"text-xs text-slate-400\" id=\"modalOrderDate\"></span>\n        </div>\n        <button onclick=\"closeOrderModal()\" class=\"text-slate-400 hover:text-slate-600 p-2 text-base\"><i class=\"fa-solid fa-xmark\"></i></button>\n      </div>\n\n      <div class=\"mt-4 space-y-4 text-xs\" id=\"modalOrderContent\"></div>\n\n      <div class=\"mt-6 flex items-center justify-between pt-4 border-t border-slate-100\">\n        <div class=\"flex items-center gap-2\">\n          <button onclick=\"window.print()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl font-bold flex items-center gap-2\">\n            <i class=\"fa-solid fa-print\"></i>\n            طباعة البوليصة\n          </button>\n          <button id=\"btnDeleteCurrentOrder\" onclick=\"deleteCurrentOrder()\" class=\"px-3 py-2 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-xl font-bold flex items-center gap-1\">\n            <i class=\"fa-solid fa-trash-can\"></i>\n            حذف الطلب\n          </button>\n        </div>\n        <button onclick=\"closeOrderModal()\" class=\"px-4 py-2 bg-brand-600 hover:bg-brand-700 text-white rounded-xl font-bold\">إغلاق</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- 8. IMAGE ZOOM PREVIEW MODAL -->\n  <div id=\"imageModal\" class=\"fixed inset-0 bg-slate-950/80 backdrop-blur-md z-50 flex items-center justify-center p-4 hidden\">\n    <div class=\"relative max-w-3xl w-full flex flex-col items-center\">\n      <button onclick=\"closeImageModal()\" class=\"absolute -top-10 left-0 text-white hover:text-rose-400 text-2xl p-2\"><i class=\"fa-solid fa-xmark\"></i></button>\n      <img id=\"modalPreviewImage\" src=\"\" alt=\"صورة الكرسي المرفوعة\" class=\"max-h-[80vh] w-auto rounded-2xl shadow-2xl border-2 border-white/20 object-contain\" />\n      <div class=\"text-white text-xs mt-3 text-center\" id=\"modalImageCaption\">صورة الكرسي المرفوعة من العميل لمقاسات التفصيل</div>\n    </div>\n  </div>\n\n  <!-- Toast Notification -->\n  <div id=\"toast\" class=\"fixed bottom-6 left-6 z-[110] bg-slate-900 text-white text-xs px-4 py-3 rounded-xl shadow-xl flex items-center gap-3 transition-transform duration-300 translate-y-24 opacity-0 pointer-events-none\">\n    <i id=\"toastIcon\" class=\"fa-solid fa-circle-check text-emerald-400\"></i>\n    <span id=\"toastMessage\">تم الإجراء بنجاح</span>\n  </div>\n\n  <!-- Main JavaScript App -->\n  <script>\n    const API_BASE = '/api';\n    let currentToken = localStorage.getItem('zahra_admin_token') || '';\n    let currentTab = 'overview';\n    let categoriesList = [];\n    let productsList = [];\n    let ordersData = [];\n    let customersData = [];\n    let expensesData = [];\n    let staffData = [];\n    let currentViewingOrderId = null;\n    let salesChartInstance = null;\n    let pendingDeleteCallback = null;\n\n    // Toast Notification Helper\n    function showToast(msg, type = 'success') {\n      const toast = document.getElementById('toast');\n      const toastMsg = document.getElementById('toastMessage');\n      const toastIcon = document.getElementById('toastIcon');\n\n      toastMsg.textContent = msg;\n      if (type === 'success') {\n        toastIcon.className = 'fa-solid fa-circle-check text-emerald-400';\n      } else {\n        toastIcon.className = 'fa-solid fa-circle-exclamation text-rose-400';\n      }\n\n      toast.classList.remove('translate-y-24', 'opacity-0', 'pointer-events-none');\n      setTimeout(() => {\n        toast.classList.add('translate-y-24', 'opacity-0', 'pointer-events-none');\n      }, 3000);\n    }\n\n    // Auth Headers\n    function getHeaders(extraHeaders = {}) {\n      const headers = { 'Content-Type': 'application/json', ...extraHeaders };\n      if (currentToken) {\n        headers['Authorization'] = `Bearer ${currentToken}`;\n      }\n      return headers;\n    }\n\n    // Authentication Checks\n    async function checkAuth() {\n      if (!currentToken) {\n        showLoginScreen();\n        return false;\n      }\n      try {\n        const res = await fetch(`${API_BASE}/auth/me`, { headers: getHeaders() });\n        if (!res.ok) {\n          showLoginScreen();\n          return false;\n        }\n        const user = await res.json();\n        document.getElementById('userNameDisplay').textContent = user.name || 'مدير متجر زهرة';\n        document.getElementById('userAvatar').textContent = (user.name || 'م').slice(0, 1);\n        document.getElementById('userRoleBadge').innerHTML = `<span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span> ${user.role === 'ADMIN' ? 'مدير عام (ADMIN)' : user.role === 'MANAGER' ? 'مشرف عمليات (MANAGER)' : 'خدمة عملاء (SUPPORT)'}`;\n        hideLoginScreen();\n        return true;\n      } catch (e) {\n        showLoginScreen();\n        return false;\n      }\n    }\n\n    function showLoginScreen() {\n      document.getElementById('loginScreen').classList.remove('hidden');\n    }\n\n    function hideLoginScreen() {\n      document.getElementById('loginScreen').classList.add('hidden');\n    }\n\n    async function handleLoginSubmit(e) {\n      e.preventDefault();\n      const email = document.getElementById('loginEmail').value.trim();\n      const password = document.getElementById('loginPassword').value;\n\n      try {\n        const res = await fetch(`${API_BASE}/auth/login`, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify({ email, password }),\n        });\n\n        if (res.ok) {\n          const data = await res.json();\n          currentToken = data.accessToken;\n          localStorage.setItem('zahra_admin_token', currentToken);\n          hideLoginScreen();\n          showToast(`مرحباً بك ${data.user.name}! تم تسجيل الدخول بنجاح`);\n          loadOverview();\n        } else {\n          showToast('البريد الإلكتروني أو كلمة المرور غير صحيحة', 'error');\n        }\n      } catch (err) {\n        showToast('تعذر الاتصال بالخادم', 'error');\n      }\n    }\n\n    function handleLogout() {\n      localStorage.removeItem('zahra_admin_token');\n      currentToken = '';\n      showToast('تم تسجيل الخروج بنجاح');\n      showLoginScreen();\n    }\n\n    function refreshCurrentTab() {\n      showToast('جاري تحديث البيانات من Supabase...');\n      switchTab(currentTab);\n    }\n\n    // ── CUSTOM IN-PLACE DELETE MODAL (Replaces browser confirm) ──\n    function openDeleteModal(title, desc, onConfirm) {\n      document.getElementById('delModalTitle').textContent = title;\n      document.getElementById('delModalDesc').textContent = desc;\n      pendingDeleteCallback = onConfirm;\n      document.getElementById('delModalConfirmBtn').onclick = () => {\n        if (pendingDeleteCallback) pendingDeleteCallback();\n        closeDeleteModal();\n      };\n      document.getElementById('deleteConfirmModal').classList.remove('hidden');\n    }\n\n    function closeDeleteModal() {\n      document.getElementById('deleteConfirmModal').classList.add('hidden');\n      pendingDeleteCallback = null;\n    }\n\n    // Tab Switcher\n    function switchTab(tabId) {\n      currentTab = tabId;\n      const panels = ['overview', 'products', 'categories', 'orders', 'custom-chairs', 'customers', 'expenses', 'shipping', 'staff'];\n      panels.forEach(p => {\n        const panel = document.getElementById(`panel-${p}`);\n        const btn = document.getElementById(`tab-btn-${p}`);\n        if (p === tabId) {\n          panel.classList.remove('hidden');\n          btn.classList.add('text-brand-700', 'bg-brand-50');\n          btn.classList.remove('text-slate-600', 'hover:bg-slate-50');\n        } else {\n          panel.classList.add('hidden');\n          btn.classList.remove('text-brand-700', 'bg-brand-50');\n          btn.classList.add('text-slate-600', 'hover:bg-slate-50');\n        }\n      });\n\n      if (tabId === 'overview') loadOverview();\n      else if (tabId === 'products') loadProducts();\n      else if (tabId === 'categories') loadCategories();\n      else if (tabId === 'orders') loadOrders();\n      else if (tabId === 'custom-chairs') loadChairRequests();\n      else if (tabId === 'customers') loadCustomers();\n      else if (tabId === 'expenses') loadExpenses();\n      else if (tabId === 'shipping') loadShippingZones();\n      else if (tabId === 'staff') loadStaffUsers();\n    }\n\n    // ── 1. OVERVIEW & FINANCIALS ──\n    async function loadOverview() {\n      try {\n        const res = await fetch(`${API_BASE}/admin/overview`, { headers: getHeaders() });\n        if (!res.ok) return;\n        const data = await res.json();\n\n        document.getElementById('kpi-revenue').textContent = `${(data.totalRevenue || 0).toLocaleString()} ج.م`;\n        document.getElementById('kpi-expenses').textContent = `${(data.totalExpenses || 0).toLocaleString()} ج.م`;\n        document.getElementById('kpi-net-profit').textContent = `${(data.netProfit || 0).toLocaleString()} ج.م`;\n        document.getElementById('kpi-orders').textContent = data.totalOrders || 0;\n        document.getElementById('kpi-pending-label').textContent = `${data.pendingOrders || 0} طلب معلق`;\n        document.getElementById('kpi-products').textContent = data.totalProducts || 0;\n        document.getElementById('kpi-clients').textContent = data.totalClients || 0;\n\n        if (data.pendingOrders > 0) {\n          const b = document.getElementById('badge-pending-orders');\n          b.textContent = data.pendingOrders;\n          b.classList.remove('hidden');\n        }\n        if (data.customRequestsCount > 0) {\n          const b = document.getElementById('badge-new-chairs');\n          b.textContent = data.customRequestsCount;\n          b.classList.remove('hidden');\n        }\n\n        // Low stock list\n        const lowStockContainer = document.getElementById('low-stock-list');\n        lowStockContainer.innerHTML = '';\n        if (data.lowStockProducts && data.lowStockProducts.length > 0) {\n          data.lowStockProducts.forEach(item => {\n            const div = document.createElement('div');\n            div.className = 'flex items-center justify-between p-2.5 rounded-xl bg-slate-50 border border-slate-100 text-xs';\n            div.innerHTML = `\n              <span class=\"font-medium text-slate-800\">${item.name_ar}</span>\n              <span class=\"px-2 py-0.5 rounded-full font-bold ${item.stock_quantity <= 5 ? 'bg-rose-100 text-rose-700' : 'bg-amber-100 text-amber-700'}\">\n                متبقي ${item.stock_quantity}\n              </span>\n            `;\n            lowStockContainer.appendChild(div);\n          });\n        } else {\n          lowStockContainer.innerHTML = '<div class=\"text-xs text-slate-400 py-3 text-center\">لا توجد منتجات منخفضة المخزون</div>';\n        }\n\n        // Recent Orders\n        const ordersTbody = document.getElementById('overview-orders-tbody');\n        ordersTbody.innerHTML = '';\n        (data.recentOrders || []).forEach(o => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-brand-700\">${o.order_number || o.orderNumber}</td>\n            <td class=\"p-3\">${o.customer_name || (o.customer ? o.customer.firstName + ' ' + o.customer.lastName : '')}</td>\n            <td class=\"p-3\">${o.governorate || o.address?.governorate || '-'}</td>\n            <td class=\"p-3 font-semibold\">${o.total_amount || o.total} ج.م</td>\n            <td class=\"p-3\">${renderStatusBadge(o.status)}</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(o.created_at || o.createdAt).toLocaleDateString('ar-EG')}</td>\n          `;\n          ordersTbody.appendChild(tr);\n        });\n\n        renderSalesChart(data.salesChart || []);\n      } catch (e) {\n        console.warn('Overview error:', e);\n      }\n    }\n\n    function renderSalesChart(chartData) {\n      const ctx = document.getElementById('salesChartCanvas').getContext('2d');\n      if (salesChartInstance) salesChartInstance.destroy();\n\n      salesChartInstance = new Chart(ctx, {\n        type: 'line',\n        data: {\n          labels: chartData.map(d => d.day),\n          datasets: [{\n            label: 'المبيعات اليومية (ج.م)',\n            data: chartData.map(d => d.sales),\n            borderColor: '#db2777',\n            backgroundColor: 'rgba(219, 39, 119, 0.1)',\n            fill: true,\n            tension: 0.4,\n            borderWidth: 3,\n            pointBackgroundColor: '#be185d',\n            pointRadius: 4,\n          }]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: { legend: { display: false } },\n          scales: {\n            y: { beginAtZero: true, grid: { color: '#f1f5f9' }, ticks: { font: { family: 'Cairo' } } },\n            x: { grid: { display: false }, ticks: { font: { family: 'Cairo' } } }\n          }\n        }\n      });\n    }\n\n    function renderStatusBadge(status) {\n      const map = {\n        pending: { text: 'معلق', class: 'bg-amber-100 text-amber-800' },\n        confirmed: { text: 'مؤكد', class: 'bg-blue-100 text-blue-800' },\n        processing: { text: 'قيد التجهيز', class: 'bg-purple-100 text-purple-800' },\n        shipped: { text: 'تم الشحن', class: 'bg-indigo-100 text-indigo-800' },\n        delivered: { text: 'تم التسليم', class: 'bg-emerald-100 text-emerald-800' },\n        cancelled: { text: 'ملغي', class: 'bg-rose-100 text-rose-800' },\n        new: { text: 'جديد', class: 'bg-rose-100 text-rose-800' },\n        contacted: { text: 'تم التواصل', class: 'bg-blue-100 text-blue-800' },\n        in_tailoring: { text: 'جاري التفصيل', class: 'bg-amber-100 text-amber-800' },\n        completed: { text: 'مكتمل', class: 'bg-emerald-100 text-emerald-800' },\n      };\n      const info = map[status] || { text: status, class: 'bg-slate-100 text-slate-800' };\n      return `<span class=\"px-2 py-0.5 rounded-full text-[11px] font-bold ${info.class}\">${info.text}</span>`;\n    }\n\n    // ── 2. PRODUCTS ──\n    async function loadProducts() {\n      try {\n        const res = await fetch(`${API_BASE}/products`);\n        if (!res.ok) return;\n        productsList = await res.json();\n        document.getElementById('badge-products-count').textContent = productsList.length;\n\n        const tbody = document.getElementById('products-table-tbody');\n        tbody.innerHTML = '';\n        productsList.forEach(p => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          const imgUrl = (p.images && p.images[0]) ? p.images[0].url : 'https://placehold.co/100x100?text=Zahra';\n          tr.innerHTML = `\n            <td class=\"p-3\">\n              <div class=\"flex items-center gap-3\">\n                <img src=\"${imgUrl}\" class=\"w-10 h-10 rounded-lg object-cover border border-slate-100\" />\n                <div>\n                  <div class=\"font-bold text-slate-900\">${p.name}</div>\n                  <div class=\"text-[10px] text-slate-400 font-mono\">${p.slug}</div>\n                </div>\n              </div>\n            </td>\n            <td class=\"p-3 text-slate-600\">${p.categoryName || p.category}</td>\n            <td class=\"p-3 font-bold text-slate-900\">${p.price} ج.م</td>\n            <td class=\"p-3 text-slate-400\">${p.originalPrice ? p.originalPrice + ' ج.م' : '-'}</td>\n            <td class=\"p-3\">${p.discount ? `<span class=\"bg-rose-100 text-rose-700 px-1.5 py-0.5 rounded font-bold text-[10px]\">${p.discount}%</span>` : '-'}</td>\n            <td class=\"p-3 font-semibold\">${p.stockCount ?? 10}</td>\n            <td class=\"p-3\">\n              <button onclick=\"toggleProductStock('${p.id}', ${!p.inStock})\" class=\"px-2.5 py-1 rounded-full text-[11px] font-bold transition-colors ${p.inStock ? 'bg-emerald-100 text-emerald-800 hover:bg-emerald-200' : 'bg-slate-200 text-slate-600 hover:bg-slate-300'}\">\n                ${p.inStock ? 'متوفر' : 'غير متوفر'}\n              </button>\n            </td>\n            <td class=\"p-3 text-center\">\n              <div class=\"flex items-center justify-center gap-2\">\n                <button onclick=\"editProduct('${p.id}')\" class=\"p-1.5 text-slate-400 hover:text-brand-600 rounded\" title=\"تعديل\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteProduct('${p.id}', '${p.name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"حذف\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Products load error:', e);\n      }\n    }\n\n    async function toggleProductStock(id, inStock) {\n      try {\n        const res = await fetch(`${API_BASE}/products/${id}/stock`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ inStock }),\n        });\n        if (res.ok) {\n          showToast('تم تحديث حالة توفر المنتج');\n          loadProducts();\n        }\n      } catch (e) {\n        showToast('فشل التحديث', 'error');\n      }\n    }\n\n    async function populateCategoryDropdown(selectedSlug = '') {\n      if (categoriesList.length === 0) {\n        const res = await fetch(`${API_BASE}/categories`);\n        if (res.ok) categoriesList = await res.json();\n      }\n      const select = document.getElementById('prodCategory');\n      select.innerHTML = '';\n      categoriesList.forEach(c => {\n        const opt = document.createElement('option');\n        opt.value = c.slug;\n        opt.textContent = c.name || c.name_ar;\n        if (c.slug === selectedSlug) opt.selected = true;\n        select.appendChild(opt);\n      });\n    }\n\n    async function openProductModal() {\n      await populateCategoryDropdown();\n      document.getElementById('productForm').reset();\n      document.getElementById('prodEditId').value = '';\n      document.getElementById('productModalTitle').textContent = 'إضافة منتج جديد';\n      document.getElementById('prodSubmitBtn').textContent = 'إضافة المنتج إلى Supabase';\n      document.getElementById('prodImagePreviewContainer').classList.add('hidden');\n      document.getElementById('productModal').classList.remove('hidden');\n    }\n\n    async function editProduct(id) {\n      const prod = productsList.find(p => p.id === id);\n      if (!prod) return;\n\n      await populateCategoryDropdown(prod.category);\n      document.getElementById('prodEditId').value = prod.id;\n      document.getElementById('prodName').value = prod.name;\n      document.getElementById('prodSlug').value = prod.slug;\n      document.getElementById('prodPrice').value = prod.price;\n      document.getElementById('prodOriginalPrice').value = prod.originalPrice || '';\n      document.getElementById('prodDiscount').value = prod.discount || '';\n      document.getElementById('prodStock').value = prod.stockCount ?? 10;\n      document.getElementById('prodMaterial').value = prod.material || '';\n      document.getElementById('prodDescription').value = prod.description || '';\n      \n      const firstImg = prod.images && prod.images[0] ? prod.images[0].url : '';\n      document.getElementById('prodImageUrl').value = firstImg;\n      if (firstImg) {\n        document.getElementById('prodImagePreview').src = firstImg;\n        document.getElementById('prodImagePreviewContainer').classList.remove('hidden');\n      } else {\n        document.getElementById('prodImagePreviewContainer').classList.add('hidden');\n      }\n\n      document.getElementById('prodInStock').checked = prod.inStock;\n      document.getElementById('prodIsFeatured').checked = !!prod.isFeatured;\n      document.getElementById('prodIsOnSale').checked = !!prod.isOnSale;\n      document.getElementById('prodIsChairCover').checked = !!prod.isChairCover;\n\n      document.getElementById('productModalTitle').textContent = `تعديل المنتج: ${prod.name}`;\n      document.getElementById('prodSubmitBtn').textContent = 'حفظ التعديلات على Supabase';\n      document.getElementById('productModal').classList.remove('hidden');\n    }\n\n    function closeProductModal() {\n      document.getElementById('productModal').classList.add('hidden');\n    }\n\n    async function uploadProductImage() {\n      const fileInput = document.getElementById('prodImageFile');\n      if (!fileInput.files || fileInput.files.length === 0) {\n        showToast('يرجى اختيار ملف صورة أولاً', 'error');\n        return;\n      }\n      const formData = new FormData();\n      formData.append('file', fileInput.files[0]);\n\n      showToast('جاري الرفع إلى Supabase Storage...');\n      try {\n        const res = await fetch(`${API_BASE}/storage/upload?bucket=products`, {\n          method: 'POST',\n          headers: { 'Authorization': `Bearer ${currentToken}` },\n          body: formData,\n        });\n\n        if (res.ok) {\n          const data = await res.json();\n          document.getElementById('prodImageUrl').value = data.url;\n          document.getElementById('prodImagePreview').src = data.url;\n          document.getElementById('prodImagePreviewContainer').classList.remove('hidden');\n          showToast('تم رفع الصورة بنجاح!');\n        } else {\n          showToast('فشل رفع الصورة', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الرفع', 'error');\n      }\n    }\n\n    async function handleProductSubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('prodEditId').value;\n      const imageUrl = document.getElementById('prodImageUrl').value.trim();\n\n      const payload = {\n        name: document.getElementById('prodName').value.trim(),\n        slug: document.getElementById('prodSlug').value.trim(),\n        category: document.getElementById('prodCategory').value,\n        price: Number(document.getElementById('prodPrice').value),\n        originalPrice: document.getElementById('prodOriginalPrice').value ? Number(document.getElementById('prodOriginalPrice').value) : undefined,\n        discount: document.getElementById('prodDiscount').value ? Number(document.getElementById('prodDiscount').value) : undefined,\n        stockCount: Number(document.getElementById('prodStock').value),\n        material: document.getElementById('prodMaterial').value.trim() || undefined,\n        description: document.getElementById('prodDescription').value.trim(),\n        inStock: document.getElementById('prodInStock').checked,\n        isFeatured: document.getElementById('prodIsFeatured').checked,\n        isOnSale: document.getElementById('prodIsOnSale').checked,\n        isChairCover: document.getElementById('prodIsChairCover').checked,\n      };\n\n      if (imageUrl) payload.images = [{ url: imageUrl, alt: payload.name, is_primary: true }];\n\n      try {\n        const url = editId ? `${API_BASE}/products/${editId}` : `${API_BASE}/products`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? 'تم تحديث المنتج بنجاح' : 'تمت إضافة المنتج بنجاح');\n          closeProductModal();\n          loadProducts();\n        } else {\n          const err = await res.json();\n          showToast(`خطأ: ${err.message || 'فشلت العملية'}`, 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الحفظ', 'error');\n      }\n    }\n\n    function confirmDeleteProduct(id, name) {\n      openDeleteModal(\n        `حذف المنتج: ${name}`,\n        `هل أنت متأكد من رغبتك في حذف المنتج \"${name}\" نهائياً من قاعدة بيانات Supabase؟`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/products/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`تم حذف المنتج \"${name}\" بنجاح`);\n              loadProducts();\n            } else {\n              showToast('فشل حذف المنتج', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    // ── 3. CATEGORIES ──\n    async function loadCategories() {\n      try {\n        const res = await fetch(`${API_BASE}/categories`);\n        if (!res.ok) return;\n        categoriesList = await res.json();\n        document.getElementById('badge-categories-count').textContent = categoriesList.length;\n\n        const grid = document.getElementById('categories-grid');\n        grid.innerHTML = '';\n        categoriesList.forEach(c => {\n          const card = document.createElement('div');\n          card.className = 'bg-white rounded-2xl border border-slate-200 p-4 shadow-sm flex flex-col justify-between';\n          card.innerHTML = `\n            <div class=\"flex items-center gap-4\">\n              <img src=\"${c.image || c.image_url || 'https://placehold.co/80x80?text=Category'}\" class=\"w-16 h-16 rounded-xl object-cover border border-slate-100\" />\n              <div class=\"flex-1\">\n                <h3 class=\"font-bold text-sm text-slate-900\">${c.name || c.name_ar}</h3>\n                <div class=\"text-[10px] text-slate-400 font-mono\">${c.slug}</div>\n                <div class=\"text-[11px] text-slate-500 mt-1 line-clamp-1\">${c.description || ''}</div>\n              </div>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 flex items-center justify-between text-xs\">\n              <span class=\"text-brand-600 font-bold\">${c.productCount || 0} منتجات</span>\n              <div class=\"flex items-center gap-2\">\n                <button onclick=\"editCategory('${c.id}')\" class=\"p-1 text-slate-400 hover:text-brand-600\" title=\"تعديل\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteCategory('${c.id}', '${c.name || c.name_ar}')\" class=\"p-1 text-slate-400 hover:text-rose-600\" title=\"حذف\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </div>\n          `;\n          grid.appendChild(card);\n        });\n      } catch (e) {\n        console.warn('Categories error:', e);\n      }\n    }\n\n    function openCategoryModal() {\n      document.getElementById('categoryForm').reset();\n      document.getElementById('catEditId').value = '';\n      document.getElementById('categoryModalTitle').textContent = 'إضافة قسم جديد';\n      document.getElementById('categoryModal').classList.remove('hidden');\n    }\n\n    function editCategory(id) {\n      const cat = categoriesList.find(c => c.id === id);\n      if (!cat) return;\n\n      document.getElementById('catEditId').value = cat.id;\n      document.getElementById('catName').value = cat.name || cat.name_ar;\n      document.getElementById('catSlug').value = cat.slug;\n      document.getElementById('catDescription').value = cat.description || '';\n      document.getElementById('catImageUrl').value = cat.image || cat.image_url || '';\n      document.getElementById('catSortOrder').value = cat.sort_order || 1;\n      document.getElementById('catIsFeatured').checked = !!cat.featured || !!cat.is_featured;\n\n      document.getElementById('categoryModalTitle').textContent = `تعديل قسم: ${cat.name || cat.name_ar}`;\n      document.getElementById('categoryModal').classList.remove('hidden');\n    }\n\n    function closeCategoryModal() {\n      document.getElementById('categoryModal').classList.add('hidden');\n    }\n\n    async function handleCategorySubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('catEditId').value;\n      const payload = {\n        name_ar: document.getElementById('catName').value.trim(),\n        slug: document.getElementById('catSlug').value.trim(),\n        description: document.getElementById('catDescription').value.trim(),\n        image_url: document.getElementById('catImageUrl').value.trim(),\n        sort_order: Number(document.getElementById('catSortOrder').value),\n        is_featured: document.getElementById('catIsFeatured').checked,\n      };\n\n      try {\n        const url = editId ? `${API_BASE}/categories/${editId}` : `${API_BASE}/categories`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? 'تم تحديث القسم بنجاح' : 'تمت إضافة القسم بنجاح');\n          closeCategoryModal();\n          loadCategories();\n        } else {\n          showToast('فشل حفظ القسم', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الحفظ', 'error');\n      }\n    }\n\n    function confirmDeleteCategory(id, name) {\n      openDeleteModal(\n        `حذف قسم: ${name}`,\n        `هل أنت متأكد من رغبتك في حذف قسم \"${name}\"؟ قد يؤثر ذلك على المنتجات المرتبطة به.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/categories/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`تم حذف قسم \"${name}\" بنجاح`);\n              loadCategories();\n            } else {\n              showToast('فشل حذف القسم', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    // ── 4. ORDERS ──\n    async function loadOrders(status = '') {\n      try {\n        let url = `${API_BASE}/orders`;\n        if (status && status !== 'all') url += `?status=${status}`;\n        const res = await fetch(url, { headers: getHeaders() });\n        if (!res.ok) return;\n        const data = await res.json();\n        ordersData = data.orders || [];\n        renderOrdersTable(ordersData);\n      } catch (e) {\n        console.warn('Orders error:', e);\n      }\n    }\n\n    function renderOrdersTable(list) {\n      const tbody = document.getElementById('orders-table-tbody');\n      tbody.innerHTML = '';\n      if (list.length === 0) {\n        tbody.innerHTML = `<tr><td colspan=\"8\" class=\"text-center py-8 text-slate-400\">لا توجد طلبات تطابق الفلتر</td></tr>`;\n        return;\n      }\n\n      list.forEach(o => {\n        const tr = document.createElement('tr');\n        tr.className = 'hover:bg-slate-50/70 transition-colors';\n        const itemCount = o.items ? o.items.length : 0;\n        tr.innerHTML = `\n          <td class=\"p-3 font-bold text-brand-700\">${o.orderNumber || o.order_number}</td>\n          <td class=\"p-3\">\n            <div class=\"font-bold text-slate-800\">${o.customer?.firstName} ${o.customer?.lastName || ''}</div>\n            <a href=\"https://wa.me/2${o.customer?.phone}\" target=\"_blank\" class=\"text-[11px] text-emerald-600 hover:underline flex items-center gap-1 font-mono\">\n              <i class=\"fa-brands fa-whatsapp\"></i> ${o.customer?.phone}\n            </a>\n          </td>\n          <td class=\"p-3\">\n            <div class=\"font-medium\">${o.address?.governorate} - ${o.address?.city}</div>\n            <div class=\"text-[10px] text-slate-400 truncate max-w-[150px]\">${o.address?.street}</div>\n          </td>\n          <td class=\"p-3\"><span class=\"bg-slate-100 text-slate-700 px-2 py-0.5 rounded-lg text-[11px] font-semibold\">${itemCount} عناصر</span></td>\n          <td class=\"p-3 font-bold text-slate-900\">${o.total} ج.م</td>\n          <td class=\"p-3 text-[11px]\">${o.paymentMethod === 'cod' ? 'دفع عند الاستلام' : o.paymentMethod}</td>\n          <td class=\"p-3\">\n            <select onchange=\"updateOrderStatus('${o.id}', this.value)\" class=\"text-[11px] bg-slate-50 border border-slate-200 rounded-lg p-1 font-semibold focus:outline-none\">\n              <option value=\"pending\" ${o.status === 'pending' ? 'selected' : ''}>معلق</option>\n              <option value=\"confirmed\" ${o.status === 'confirmed' ? 'selected' : ''}>مؤكد</option>\n              <option value=\"processing\" ${o.status === 'processing' ? 'selected' : ''}>قيد التجهيز</option>\n              <option value=\"shipped\" ${o.status === 'shipped' ? 'selected' : ''}>تم الشحن</option>\n              <option value=\"delivered\" ${o.status === 'delivered' ? 'selected' : ''}>تم التسليم</option>\n              <option value=\"cancelled\" ${o.status === 'cancelled' ? 'selected' : ''}>ملغي</option>\n            </select>\n          </td>\n          <td class=\"p-3 text-center\">\n            <div class=\"flex items-center justify-center gap-2\">\n              <button onclick=\"viewOrderDetails('${o.id}')\" class=\"p-1.5 text-brand-600 hover:bg-brand-50 rounded-lg transition-colors\" title=\"تفاصيل الطلب والفاتورة\"><i class=\"fa-solid fa-eye\"></i></button>\n              <button onclick=\"confirmDeleteOrder('${o.id}', '${o.orderNumber || o.order_number}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded-lg transition-colors\" title=\"حذف الطلب\"><i class=\"fa-solid fa-trash-can\"></i></button>\n            </div>\n          </td>\n        `;\n        tbody.appendChild(tr);\n      });\n    }\n\n    function filterOrders(status) {\n      document.querySelectorAll('[id^=\"btn-order-filter-\"]').forEach(btn => {\n        btn.className = 'px-3 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 hover:bg-slate-200 text-slate-700';\n      });\n      document.getElementById(`btn-order-filter-${status}`).className = 'px-3 py-1.5 rounded-lg text-xs font-bold bg-brand-600 text-white';\n      loadOrders(status);\n    }\n\n    function handleOrderSearch(query) {\n      const q = query.toLowerCase().trim();\n      if (!q) { renderOrdersTable(ordersData); return; }\n      const filtered = ordersData.filter(o => \n        (o.orderNumber && o.orderNumber.toLowerCase().includes(q)) ||\n        (o.customer?.phone && o.customer.phone.includes(q)) ||\n        (o.customer?.firstName && `${o.customer.firstName} ${o.customer.lastName}`.toLowerCase().includes(q))\n      );\n      renderOrdersTable(filtered);\n    }\n\n    async function updateOrderStatus(orderId, newStatus) {\n      try {\n        const res = await fetch(`${API_BASE}/orders/${orderId}/status`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ status: newStatus }),\n        });\n        if (res.ok) {\n          showToast(`تم تغيير حالة الطلب إلى \"${newStatus}\"`);\n        } else {\n          showToast('فشل تحديث الحالة', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء التحديث', 'error');\n      }\n    }\n\n    function viewOrderDetails(orderId) {\n      currentViewingOrderId = orderId;\n      const order = ordersData.find(o => o.id === orderId);\n      if (!order) return;\n\n      document.getElementById('modalOrderNumber').textContent = `طلب رقم: ${order.orderNumber}`;\n      document.getElementById('modalOrderDate').textContent = `تاريخ الإنشاء: ${new Date(order.createdAt).toLocaleString('ar-EG')}`;\n\n      const content = document.getElementById('modalOrderContent');\n      content.innerHTML = `\n        <div class=\"grid grid-cols-2 gap-4 bg-slate-50 p-4 rounded-xl border border-slate-100\">\n          <div>\n            <span class=\"text-slate-400 block text-[10px]\">بيانات العميل:</span>\n            <span class=\"font-bold text-slate-900\">${order.customer?.firstName} ${order.customer?.lastName}</span>\n            <div class=\"text-slate-600 font-mono\">${order.customer?.phone}</div>\n          </div>\n          <div>\n            <span class=\"text-slate-400 block text-[10px]\">عنوان الشحن:</span>\n            <span class=\"font-medium text-slate-800\">${order.address?.governorate} - ${order.address?.city}</span>\n            <div class=\"text-slate-600\">${order.address?.street} ${order.address?.apartment ? ' - ' + order.address.apartment : ''}</div>\n          </div>\n        </div>\n\n        <div class=\"space-y-2\">\n          <div class=\"font-bold text-slate-800\">العناصر المطلوبة:</div>\n          <div class=\"divide-y divide-slate-100 border border-slate-100 rounded-xl overflow-hidden\">\n            ${(order.items || []).map(item => `\n              <div class=\"p-3 bg-white flex items-center justify-between gap-3\">\n                <div class=\"flex items-center gap-3\">\n                  ${item.image ? `<img src=\"${item.image}\" class=\"w-12 h-12 rounded-lg object-cover\" />` : ''}\n                  <div>\n                    <div class=\"font-bold text-slate-900\">${item.name}</div>\n                    <div class=\"text-[11px] text-slate-500\">الكمية: ${item.quantity} × ${item.price} ج.م</div>\n                    ${item.selectedVariants ? `\n                      <div class=\"text-[10px] text-brand-600 mt-1\">\n                        ${Object.entries(item.selectedVariants).map(([k, v]) => `${k}: <b>${v}</b>`).join(' | ')}\n                      </div>\n                    ` : ''}\n                  </div>\n                </div>\n                <div class=\"text-left font-bold text-slate-900\">${item.price * item.quantity} ج.م</div>\n              </div>\n            `).join('')}\n          </div>\n        </div>\n\n        <div class=\"bg-brand-50/50 p-3 rounded-xl space-y-1 text-slate-700\">\n          <div class=\"flex justify-between\"><span>المجموع الفرعي:</span><span>${order.subtotal} ج.م</span></div>\n          <div class=\"flex justify-between\"><span>مصاريف الشحن:</span><span>${order.shippingCost} ج.م</span></div>\n          ${order.discount ? `<div class=\"flex justify-between text-emerald-600\"><span>الخصم:</span><span>-${order.discount} ج.م</span></div>` : ''}\n          <div class=\"flex justify-between font-black text-sm text-slate-900 pt-1 border-t border-brand-100\">\n            <span>الإجمالي النهائي:</span>\n            <span>${order.total} ج.م</span>\n          </div>\n        </div>\n      `;\n\n      document.getElementById('orderModal').classList.remove('hidden');\n    }\n\n    function closeOrderModal() {\n      document.getElementById('orderModal').classList.add('hidden');\n    }\n\n    function confirmDeleteOrder(id, orderNumber) {\n      openDeleteModal(\n        `حذف الطلب: ${orderNumber}`,\n        `هل أنت متأكد من رغبتك في حذف الطلب \"${orderNumber}\" نهائياً من قاعدة بيانات Supabase؟`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/orders/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`تم حذف الطلب \"${orderNumber}\" بنجاح`);\n              loadOrders();\n            } else {\n              showToast('فشل حذف الطلب', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    function deleteCurrentOrder() {\n      if (currentViewingOrderId) {\n        closeOrderModal();\n        confirmDeleteOrder(currentViewingOrderId, 'المحدد');\n      }\n    }\n\n    // ── 5. CUSTOM CHAIRS ──\n    async function loadChairRequests() {\n      try {\n        const res = await fetch(`${API_BASE}/chair-custom`, { headers: getHeaders() });\n        if (!res.ok) return;\n        const requests = await res.json();\n\n        const grid = document.getElementById('chair-requests-grid');\n        grid.innerHTML = '';\n        if (requests.length === 0) {\n          grid.innerHTML = `<div class=\"col-span-3 text-center py-12 text-slate-400 bg-white rounded-2xl border border-slate-200\">لا توجد طلبات كراسي عمولة جديدة حالياً</div>`;\n          return;\n        }\n\n        requests.forEach(req => {\n          const card = document.createElement('div');\n          card.className = 'bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm flex flex-col justify-between hover:shadow-md transition-shadow';\n          card.innerHTML = `\n            <div>\n              <div class=\"relative h-48 bg-slate-100 group cursor-pointer overflow-hidden\" onclick=\"openImageModal('${req.uploaded_photo_url}', 'صورة كرسي العميل: ${req.customer_name}')\">\n                <img src=\"${req.uploaded_photo_url}\" alt=\"صورة الكرسي\" class=\"w-full h-full object-cover group-hover:scale-105 transition-transform duration-300\" />\n                <div class=\"absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white gap-2 font-bold text-xs\">\n                  <i class=\"fa-solid fa-magnifying-glass-plus text-lg\"></i>\n                  معاينة وتكبير الصورة\n                </div>\n                <div class=\"absolute top-3 right-3\">${renderStatusBadge(req.status)}</div>\n              </div>\n\n              <div class=\"p-4 space-y-3\">\n                <div class=\"flex items-center justify-between\">\n                  <h3 class=\"font-bold text-sm text-slate-900\">${req.customer_name}</h3>\n                  <span class=\"text-xs font-semibold text-brand-700\">+${req.custom_extra_fee} ج.م (عمولة)</span>\n                </div>\n                <div class=\"text-xs text-slate-500 font-mono\">${req.customer_phone}</div>\n\n                <div class=\"bg-slate-50 p-2.5 rounded-xl border border-slate-100 space-y-1 text-xs\">\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">اللون المختار:</span><span class=\"font-bold text-slate-800\">${req.fabric_color}</span></div>\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">النقشة:</span><span class=\"font-bold text-slate-800\">${req.pattern_type}</span></div>\n                  <div class=\"flex justify-between\"><span class=\"text-slate-400\">عدد الكراسي:</span><span class=\"font-bold text-slate-800\">${req.chairs_count} كراسي</span></div>\n                </div>\n\n                ${req.admin_notes ? `<div class=\"text-[11px] text-amber-700 bg-amber-50 p-2 rounded-lg border border-amber-100 font-medium\">ملاحظات: ${req.admin_notes}</div>` : ''}\n              </div>\n            </div>\n\n            <div class=\"p-4 pt-0 border-t border-slate-100 space-y-2\">\n              <a href=\"${req.whatsapp_link}\" target=\"_blank\" class=\"w-full py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-xl text-xs flex items-center justify-center gap-2 shadow-sm transition-colors\">\n                <i class=\"fa-brands fa-whatsapp text-sm\"></i>\n                بدء محادثة واتساب مع العميل\n              </a>\n              <div class=\"flex items-center justify-between text-[11px] pt-1\">\n                <span class=\"text-slate-400\">تحديث الحالة:</span>\n                <select onchange=\"updateChairStatus('${req.id}', this.value)\" class=\"bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 font-semibold text-xs focus:outline-none\">\n                  <option value=\"new\" ${req.status === 'new' ? 'selected' : ''}>جديد</option>\n                  <option value=\"contacted\" ${req.status === 'contacted' ? 'selected' : ''}>تم التواصل</option>\n                  <option value=\"in_tailoring\" ${req.status === 'in_tailoring' ? 'selected' : ''}>جاري التفصيل</option>\n                  <option value=\"completed\" ${req.status === 'completed' ? 'selected' : ''}>مكتمل</option>\n                  <option value=\"cancelled\" ${req.status === 'cancelled' ? 'selected' : ''}>ملغي</option>\n                </select>\n              </div>\n            </div>\n          `;\n          grid.appendChild(card);\n        });\n      } catch (e) {\n        console.warn('Chair requests error:', e);\n      }\n    }\n\n    async function updateChairStatus(reqId, status) {\n      try {\n        const res = await fetch(`${API_BASE}/chair-custom/${reqId}/status`, {\n          method: 'PATCH',\n          headers: getHeaders(),\n          body: JSON.stringify({ status }),\n        });\n        if (res.ok) {\n          showToast('تم تحديث حالة طلب التفصيل في Supabase');\n        } else {\n          showToast('فشل التحديث', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ', 'error');\n      }\n    }\n\n    function openImageModal(url, caption) {\n      document.getElementById('modalPreviewImage').src = url;\n      document.getElementById('modalImageCaption').textContent = caption;\n      document.getElementById('imageModal').classList.remove('hidden');\n    }\n\n    function closeImageModal() {\n      document.getElementById('imageModal').classList.add('hidden');\n    }\n\n    // ── 6. CLIENTS / CUSTOMERS CRM ──\n    async function loadCustomers() {\n      try {\n        const res = await fetch(`${API_BASE}/customers`, { headers: getHeaders() });\n        if (!res.ok) return;\n        customersData = await res.json();\n        document.getElementById('badge-clients-count').textContent = customersData.length;\n\n        const tbody = document.getElementById('customers-table-tbody');\n        tbody.innerHTML = '';\n        if (customersData.length === 0) {\n          tbody.innerHTML = `<tr><td colspan=\"6\" class=\"text-center py-8 text-slate-400\">لا يوجد عملاء مسجلين بعد. اضغط \"إضافة عميل جديد\" لإضافة أول عميل!</td></tr>`;\n          return;\n        }\n\n        customersData.forEach(c => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3\">\n              <div class=\"font-bold text-slate-900\">${c.name}</div>\n              <div class=\"text-[10px] text-slate-400 font-mono\">${c.email || ''}</div>\n            </td>\n            <td class=\"p-3 font-mono font-medium\">${c.phone}</td>\n            <td class=\"p-3 text-slate-600\">${c.governorate || '-'} ${c.city ? ' - ' + c.city : ''}</td>\n            <td class=\"p-3 font-semibold\">${c.totalOrders} طلبات</td>\n            <td class=\"p-3 font-bold text-emerald-600\">${(c.totalSpend || 0).toLocaleString()} ج.م</td>\n            <td class=\"p-3 text-center\">\n              <div class=\"flex items-center justify-center gap-2\">\n                <a href=\"https://wa.me/2${c.phone}\" target=\"_blank\" class=\"px-2 py-1 bg-emerald-50 text-emerald-700 hover:bg-emerald-100 font-bold rounded-lg text-xs inline-flex items-center gap-1\" title=\"واتساب فوري\">\n                  <i class=\"fa-brands fa-whatsapp text-sm\"></i>\n                  واتساب\n                </a>\n                <button onclick=\"editCustomer('${c.id}')\" class=\"p-1.5 text-slate-400 hover:text-brand-600 rounded\" title=\"تعديل\"><i class=\"fa-solid fa-pen-to-square\"></i></button>\n                <button onclick=\"confirmDeleteCustomer('${c.id}', '${c.name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"حذف\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              </div>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Customers error:', e);\n      }\n    }\n\n    function openCustomerModal() {\n      document.getElementById('customerForm').reset();\n      document.getElementById('custEditId').value = '';\n      document.getElementById('customerModalTitle').textContent = 'إضافة عميل جديد';\n      document.getElementById('customerModal').classList.remove('hidden');\n    }\n\n    function editCustomer(id) {\n      const cust = customersData.find(c => c.id === id);\n      if (!cust) return;\n\n      document.getElementById('custEditId').value = cust.id;\n      document.getElementById('custName').value = cust.name;\n      document.getElementById('custPhone').value = cust.phone;\n      document.getElementById('custEmail').value = cust.email || '';\n      document.getElementById('custGovernorate').value = cust.governorate || '';\n      document.getElementById('custCity').value = cust.city || '';\n      document.getElementById('custAddress').value = cust.street_address || '';\n      document.getElementById('custNotes').value = cust.notes || '';\n\n      document.getElementById('customerModalTitle').textContent = `تعديل بيانات العميل: ${cust.name}`;\n      document.getElementById('customerModal').classList.remove('hidden');\n    }\n\n    function closeCustomerModal() {\n      document.getElementById('customerModal').classList.add('hidden');\n    }\n\n    async function handleCustomerSubmit(e) {\n      e.preventDefault();\n      const editId = document.getElementById('custEditId').value;\n      const payload = {\n        name: document.getElementById('custName').value.trim(),\n        phone: document.getElementById('custPhone').value.trim(),\n        email: document.getElementById('custEmail').value.trim() || undefined,\n        governorate: document.getElementById('custGovernorate').value.trim() || undefined,\n        city: document.getElementById('custCity').value.trim() || undefined,\n        street_address: document.getElementById('custAddress').value.trim() || undefined,\n        notes: document.getElementById('custNotes').value.trim() || undefined,\n      };\n\n      try {\n        const url = editId ? `${API_BASE}/customers/${editId}` : `${API_BASE}/customers`;\n        const method = editId ? 'PUT' : 'POST';\n        const res = await fetch(url, {\n          method,\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast(editId ? 'تم تحديث بيانات العميل بنجاح' : 'تمت إضافة العميل بنجاح');\n          closeCustomerModal();\n          loadCustomers();\n        } else {\n          const err = await res.json();\n          showToast(`خطأ: ${err.message || 'فشلت العملية'}`, 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء حفظ العميل', 'error');\n      }\n    }\n\n    function confirmDeleteCustomer(id, name) {\n      openDeleteModal(\n        `حذف العميل: ${name}`,\n        `هل أنت متأكد من رغبتك في حذف العميل \"${name}\" من قاعدة بيانات Supabase؟`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/customers/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`تم حذف العميل \"${name}\" بنجاح`);\n              loadCustomers();\n            } else {\n              showToast('فشل حذف العميل', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    // ── 7. EXPENSES ──\n    async function loadExpenses() {\n      try {\n        const res = await fetch(`${API_BASE}/expenses`, { headers: getHeaders() });\n        if (!res.ok) return;\n        expensesData = await res.json();\n\n        const tbody = document.getElementById('expenses-table-tbody');\n        tbody.innerHTML = '';\n        if (expensesData.length === 0) {\n          tbody.innerHTML = `<tr><td colspan=\"6\" class=\"text-center py-8 text-slate-400\">لا توجد بنود مصروفات مسجلة بعد</td></tr>`;\n          return;\n        }\n\n        expensesData.forEach(exp => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-slate-900\">${exp.title}</td>\n            <td class=\"p-3\"><span class=\"px-2 py-0.5 rounded-lg text-[10px] font-bold bg-slate-100 text-slate-700\">${exp.category.replace('_', ' ')}</span></td>\n            <td class=\"p-3 font-bold text-rose-600 font-mono\">${(exp.amount || 0).toLocaleString()} ج.م</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(exp.date).toLocaleDateString('ar-EG')}</td>\n            <td class=\"p-3 text-slate-500\">${exp.notes || '-'}</td>\n            <td class=\"p-3 text-center\">\n              <button onclick=\"confirmDeleteExpense('${exp.id}', '${exp.title}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"حذف\"><i class=\"fa-solid fa-trash-can\"></i></button>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Expenses error:', e);\n      }\n    }\n\n    function openExpenseModal() {\n      document.getElementById('expenseForm').reset();\n      document.getElementById('expenseModal').classList.remove('hidden');\n    }\n\n    function closeExpenseModal() {\n      document.getElementById('expenseModal').classList.add('hidden');\n    }\n\n    async function handleExpenseSubmit(e) {\n      e.preventDefault();\n      const payload = {\n        title: document.getElementById('expTitle').value.trim(),\n        amount: Number(document.getElementById('expAmount').value),\n        category: document.getElementById('expCategory').value,\n        notes: document.getElementById('expNotes').value.trim() || undefined,\n      };\n\n      try {\n        const res = await fetch(`${API_BASE}/expenses`, {\n          method: 'POST',\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast('تم تسجيل المصروف بنجاح');\n          closeExpenseModal();\n          loadExpenses();\n          loadOverview(); // update financials\n        } else {\n          showToast('فشل تسجيل المصروف', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الحفظ', 'error');\n      }\n    }\n\n    function confirmDeleteExpense(id, title) {\n      openDeleteModal(\n        `حذف المصروف: ${title}`,\n        `هل أنت متأكد من حذف هذا المصروف؟ سيتم إعادة حساب صافي الأرباح تلقائياً.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/expenses/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast('تم حذف المصروف بنجاح');\n              loadExpenses();\n              loadOverview();\n            } else {\n              showToast('فشل الحذف', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    // ── 8. SHIPPING ZONES (With Clear Arabic Badges & Status) ──\n    async function loadShippingZones() {\n      try {\n        const res = await fetch(`${API_BASE}/shipping/zones`);\n        if (!res.ok) return;\n        const zones = await res.json();\n\n        const tbody = document.getElementById('shipping-table-tbody');\n        tbody.innerHTML = '';\n        zones.forEach(z => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-slate-900\">${z.governorate_name_ar}</td>\n            <td class=\"p-3\">\n              <input type=\"number\" id=\"fee-${z.id}\" value=\"${z.shipping_fee}\" class=\"w-20 text-xs bg-slate-50 border border-slate-200 rounded p-1 text-center font-bold\" />\n            </td>\n            <td class=\"p-3\">\n              <input type=\"text\" id=\"days-${z.id}\" value=\"${z.estimated_days}\" class=\"w-36 text-xs bg-slate-50 border border-slate-200 rounded p-1 font-medium\" />\n            </td>\n            <td class=\"p-3\">\n              <div class=\"flex items-center gap-3\">\n                <label class=\"inline-flex items-center cursor-pointer\">\n                  <input type=\"checkbox\" id=\"active-${z.id}\" onchange=\"toggleShippingBadge('${z.id}')\" ${z.is_active ? 'checked' : ''} class=\"sr-only peer\">\n                  <div class=\"w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:right-[2px] after:bg-white after:border-slate-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600\"></div>\n                </label>\n                <span id=\"badge-shipping-${z.id}\">\n                  ${z.is_active \n                    ? `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 flex items-center gap-1.5\"><span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>متاح للتوصيل</span>` \n                    : `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500\">التوصيل متوقف</span>`}\n                </span>\n              </div>\n            </td>\n            <td class=\"p-3 text-center\">\n              <button onclick=\"saveZone('${z.id}', '${z.governorate_name_ar}')\" class=\"px-3 py-1 bg-brand-50 hover:bg-brand-100 text-brand-700 font-bold rounded-lg text-xs transition-colors\">\n                حفظ على Supabase\n              </button>\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Shipping zones error:', e);\n      }\n    }\n\n    function toggleShippingBadge(id) {\n      const isChecked = document.getElementById(`active-${id}`).checked;\n      const badgeSpan = document.getElementById(`badge-shipping-${id}`);\n      if (isChecked) {\n        badgeSpan.innerHTML = `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-emerald-100 text-emerald-800 flex items-center gap-1.5\"><span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse\"></span>متاح للتوصيل</span>`;\n      } else {\n        badgeSpan.innerHTML = `<span class=\"px-2.5 py-1 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500\">التوصيل متوقف</span>`;\n      }\n    }\n\n    async function saveZone(id, name) {\n      const fee = Number(document.getElementById(`fee-${id}`).value);\n      const days = document.getElementById(`days-${id}`).value;\n      const isActive = document.getElementById(`active-${id}`).checked;\n\n      try {\n        const res = await fetch(`${API_BASE}/shipping/zones/${id}`, {\n          method: 'PUT',\n          headers: getHeaders(),\n          body: JSON.stringify({ shipping_fee: fee, estimated_days: days, is_active: isActive }),\n        });\n        if (res.ok) {\n          showToast(`تم حفظ تعديل محافظة ${name} على Supabase`);\n        } else {\n          showToast('فشل التعديل', 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الحفظ', 'error');\n      }\n    }\n\n    // ── 9. STAFF & ROLES ──\n    async function loadStaffUsers() {\n      try {\n        const res = await fetch(`${API_BASE}/admin/users`, { headers: getHeaders() });\n        if (!res.ok) return;\n        staffData = await res.json();\n\n        const tbody = document.getElementById('staff-table-tbody');\n        tbody.innerHTML = '';\n        staffData.forEach(u => {\n          const tr = document.createElement('tr');\n          tr.className = 'hover:bg-slate-50/70 transition-colors';\n          const roleLabel = u.role === 'ADMIN' ? 'مدير عام (ADMIN)' : u.role === 'MANAGER' ? 'مشرف عمليات (MANAGER)' : 'خدمة عملاء (SUPPORT)';\n          const roleColor = u.role === 'ADMIN' ? 'bg-purple-100 text-purple-800' : u.role === 'MANAGER' ? 'bg-blue-100 text-blue-800' : 'bg-teal-100 text-teal-800';\n\n          tr.innerHTML = `\n            <td class=\"p-3 font-bold text-slate-900\">${u.full_name}</td>\n            <td class=\"p-3 font-mono text-slate-600\">${u.email}</td>\n            <td class=\"p-3\"><span class=\"px-2.5 py-1 rounded-full text-[10px] font-bold ${roleColor}\">${roleLabel}</span></td>\n            <td class=\"p-3\">${u.is_active ? '<span class=\"text-emerald-600 font-bold\">نشط</span>' : '<span class=\"text-slate-400\">معطل</span>'}</td>\n            <td class=\"p-3 text-slate-400 font-mono\">${new Date(u.created_at).toLocaleDateString('ar-EG')}</td>\n            <td class=\"p-3 text-center\">\n              ${u.email !== 'admin@zahra-store.com' ? `\n                <button onclick=\"confirmDeleteStaff('${u.id}', '${u.full_name}')\" class=\"p-1.5 text-slate-400 hover:text-rose-600 rounded\" title=\"حذف المشرف\"><i class=\"fa-solid fa-trash-can\"></i></button>\n              ` : '<span class=\"text-[10px] text-slate-400\">المدير الأساسي</span>'}\n            </td>\n          `;\n          tbody.appendChild(tr);\n        });\n      } catch (e) {\n        console.warn('Staff error:', e);\n      }\n    }\n\n    function openStaffModal() {\n      document.getElementById('staffForm').reset();\n      document.getElementById('staffModal').classList.remove('hidden');\n    }\n\n    function closeStaffModal() {\n      document.getElementById('staffModal').classList.add('hidden');\n    }\n\n    async function handleStaffSubmit(e) {\n      e.preventDefault();\n      const payload = {\n        full_name: document.getElementById('staffName').value.trim(),\n        email: document.getElementById('staffEmail').value.trim(),\n        password: document.getElementById('staffPassword').value,\n        role: document.getElementById('staffRole').value,\n      };\n\n      try {\n        const res = await fetch(`${API_BASE}/admin/users`, {\n          method: 'POST',\n          headers: getHeaders(),\n          body: JSON.stringify(payload),\n        });\n\n        if (res.ok) {\n          showToast('تمت إضافة المشرف بنجاح');\n          closeStaffModal();\n          loadStaffUsers();\n        } else {\n          const err = await res.json();\n          showToast(`خطأ: ${err.message || 'فشلت العملية'}`, 'error');\n        }\n      } catch (e) {\n        showToast('حدث خطأ أثناء الحفظ', 'error');\n      }\n    }\n\n    function confirmDeleteStaff(id, name) {\n      openDeleteModal(\n        `حذف المشرف: ${name}`,\n        `هل أنت متأكد من رغبتك في حذف المشرف \"${name}\"؟ سيفقد حق الوصول للوحة التحكم.`,\n        async () => {\n          try {\n            const res = await fetch(`${API_BASE}/admin/users/${id}`, {\n              method: 'DELETE',\n              headers: getHeaders(),\n            });\n            if (res.ok) {\n              showToast(`تم حذف المشرف \"${name}\" بنجاح`);\n              loadStaffUsers();\n            } else {\n              showToast('فشل حذف المشرف', 'error');\n            }\n          } catch (e) {\n            showToast('حدث خطأ أثناء الحذف', 'error');\n          }\n        }\n      );\n    }\n\n    // App Initialization\n    window.addEventListener('DOMContentLoaded', async () => {\n      const isAuth = await checkAuth();\n      if (isAuth) {\n        loadOverview();\n      }\n    });\n  </script>\n</body>\n</html>\n";
